/**
 * The administrator's allowlisted view of a metadata lookup record: an import's (GET /imports/:id/lookup) or an existing-Album
 * review's (GET /catalog-reviews/:id/lookup). It carries bounded candidate evidence (an iTunes-only candidate marked as such, and
 * whether it was not checked against MusicBrainz), groups, the preselection, the applied values with their conflicts and flags, the
 * iTunes stage's status, what Publish waits for and a submitted run's name with any submitted Artist name; never a URL, ISRC,
 * recording ID, storefront, localized name, account, grant, lease, fence, file-set digest or query. A review's view also admits
 * the catalog trigger, the exact-count basis, the subset differences, each candidate's subset comparison and `byTrackTitle`, the
 * review-only value paths (expected tracklist, member Artist entries), the review-only flag reasons, each conflict's `precision`,
 * the applied pairing (`pairs`) and, while its run is queued, running or retrying, `progress`: its phase, the done and total counts
 * of that phase's bounded steps and the run's start and last-step times (numbers and times only, never a query); an import's view
 * never carries them. Pure.
 */
import type { ImportDate } from '../import/adminImportContract';
import { importDraftV2View } from '../import/adminImportDraftCompat';
import type { AdminImportDocument } from '../import/adminImportService';
import { parseDraftValue, type ImportDraftPath } from '../import/adminImportValueState';
import type { MusicBrainzRelease, MusicBrainzReleaseSummary } from './lookupContract';
import type { LookupDifference, LookupMatchStatus, LookupPreselection, LookupProposal, LookupSubsetDifference } from './lookupRanking';
import { REVIEW_LOOKUP_LIMITS } from './lookupReviewValues';
import { LOOKUP_EXPECTED_TRACKLIST_BOUNDS } from './lookupSubset';
import { isLookupValuePath, lookupAnswersNeeded, lookupValueIds } from './lookupValueApplication';
import { lookupCandidateSource } from './lookupContract';
import { normalizeMusicBrainzId } from './lookupIdentifiers';
import { isTrackTitleLookupQuery } from './lookupQueryPlanner';
import { storedItunesStage } from './lookupItunesStage';
import { isBlockingLookupState, type LookupApplication, type MetadataLookupIssue, type MetadataLookupRecord, type MetadataLookupState } from './metadataLookupRecord';

/** A ranked candidate's counts and differences; the per-file comparison stays internal. */
type ViewComparison = { trackCount: { local: number; candidate: number }; discCount: { local: number | null; candidate: number }; differences: LookupDifference[];
    unknownLocalDurations: number; unknownCandidateDurations: number };
/**
 * A review candidate's subset comparison: tracks left out as video, data or pregap, the pairing and its pairs (members of this
 * review only), how many missing-file rows the release would add, and the members no audio track can pair with.
 */
export type ViewSubsetComparison = { leftOutTracks: number; pairing: 'unique' | 'ambiguous' | 'none' | null; pairs: { slotId: string; discNumber: number; trackNumber: number }[];
    missingTrackCount: number | null; unpairableSlotIds: string[] };
type ViewReviewComparison = Omit<ViewComparison, 'differences'> & { differences: (LookupDifference | LookupSubsetDifference)[]; subset: ViewSubsetComparison | null };
/**
 * One candidate's evidence. An iTunes-only candidate (`source` itunes, its collection ID as `releaseId`) shows no label, catalogue
 * number, country or medium, and only a barcode a UPC lookup found; `notChecked` marks one that was not checked against MusicBrainz.
 */
type ViewCandidate<Comparison = ViewComparison> = {
    key: string; releaseId: string; source: 'musicbrainz' | 'itunes'; notChecked: boolean; status: LookupMatchStatus; title: string | null; artist: string | null; label: string | null;
    catalogNumber: string | null; barcode: string | null; country: string | null; date: ImportDate | null; formats: string[]; trackCount: number | null;
    comparison: Comparison | null;
    groupKey: string | null; artistMismatch: boolean | null;
    /** Whether the fetched release reports front artwork (a protected preview exists); never an address. */
    artwork: boolean;
    /** A review's only, and only `true`: its release was first found by a Track-title search. */
    byTrackTitle?: true;
};
/** The iTunes stage: not queried (none, or a run that ended before it), running, waiting for an automatic retry, answered or unavailable. */
export type ImportLookupItunesStatus = 'notQueried' | 'running' | 'retrying' | 'answered' | 'unavailable';
type LookupRecordView<Trigger extends string, Comparison> = {
    run: number; state: MetadataLookupState; issue: MetadataLookupIssue | null; outcome: 'candidates' | 'noRelease' | 'noQuery' | null;
    /** `artist`: present only when the run was submitted with an Artist name (a bounded string). */
    input: { trigger: Trigger; submitted: { kind: 'album' | 'song'; text: string; artist?: string } | null };
    candidates: ViewCandidate<Comparison>[];
    groups: { groupKey: string; representativeKey: string; memberKeys: string[]; proposal: LookupProposal }[];
    preselection: Pick<LookupPreselection, 'candidateKey' | 'basis' | 'artistMismatch'> & { notChecked: boolean } | null;
    /** `partialComparison`: not every release found was compared (false for a ranking stored before it was recorded). */
    disclosure: { unknownLocalDurations: number; unknownLocalDiscNumbers: number; partialComparison: boolean } | null;
    applied: {
        run: number; candidateKey: string | null; releaseId: string | null; choice: LookupApplication['choice']; basis: LookupApplication['basis'];
        /** The applied candidate's source and whether it was not checked against MusicBrainz (an iTunes-only candidate's values stay flagged). */
        source: 'musicbrainz' | 'itunes'; notChecked: boolean;
        values: { path: string; slotId: string | null }[];
        /** `musicBrainzId`: the values differ only in MusicBrainz IDs. `precision` (a review's only): a date that only adds precision. */
        conflicts: { path: string; slotId: string | null; lookup: unknown; answer: 'mine' | 'lookup' | null; musicBrainzId: boolean; precision?: boolean }[];
        flagged: { path: string; reason: LookupApplication['flagged'][number]['reason'] }[];
        /** A review's only: the single pairing the applied values rest on, `null` without one. */
        pairs?: { slotId: string; discNumber: number; trackNumber: number }[] | null;
    } | null;
    staleFiles: string[]; needsAnswer: { tie: boolean; conflicts: string[] }; blocking: boolean; itunes: ImportLookupItunesStatus;
};
export type ImportLookupView = LookupRecordView<'tags' | 'folder' | 'submitted', ViewComparison>;
/**
 * A review's active run: its phase, the done and total counts of that phase's bounded steps (each within 100), and the run's start
 * (`createdAt`, as each run is stored afresh) and last-step (`updatedAt`) times.
 */
export type ViewLookupProgress = { phase: 'search' | 'details' | 'itunes' | 'bridge' | 'aliases'; done: number; total: number; startedAt: string; updatedAt: string };
/**
 * A review's view: the catalog trigger, each candidate's comparison with the subset differences and its subset comparison, and an
 * active run's `progress` (the key is absent otherwise, so a Web tab opened before it still parses every finished run).
 */
export type CatalogReviewLookupView = LookupRecordView<'tags' | 'folder' | 'submitted' | 'catalog', ViewReviewComparison> & { progress?: ViewLookupProgress };
type ViewMode = 'import' | 'review';

const states: readonly MetadataLookupState[] = ['queued', 'running', 'retrying', 'complete', 'unavailable', 'stopped', 'superseded'];
const issues: readonly MetadataLookupIssue[] = ['permissionLost', 'grantExpired', 'notConfigured', 'sourceUnavailable', 'sourceBusy', 'fileSetChanged', 'projectClosed'];
const statuses: readonly LookupMatchStatus[] = ['matching', 'unverified', 'notMatching', 'incomplete'];
const differences: readonly LookupDifference[] = ['trackCount', 'discCount', 'duration'];
const reviewDifferences: readonly (LookupDifference | LookupSubsetDifference)[] = [...differences, 'pairing', 'tooManyTracks', 'tracklistInvalid'];
const bases: readonly string[] = ['releaseId', 'barcode', 'catalogNumber', 'onlyMatchingGroup'];
const reviewBases: readonly string[] = [...bases, 'exactTrackCount'];
const triggers = ['tags', 'folder', 'submitted'] as const, reviewTriggers = [...triggers, 'catalog'] as const;
const flagReasons: readonly string[] = ['characters', 'length', 'format', 'size', 'placeholder'];
const reviewFlagReasons: readonly string[] = [...flagReasons, 'notApplicable', 'noTrackCredit'];
/** The phases an active run reports progress for; `done` belongs to a completed run, which shows none. */
const progressPhases = ['search', 'details', 'itunes', 'bridge', 'aliases'] as const;
/**
 * `values` bounds applied values, conflicts and flags: one per value path (an import's 305, a review's 406, REVIEW_LOOKUP_LIMITS.answers).
 * `progress` bounds a phase's done and total counts.
 */
const LIMITS = Object.freeze({ candidates: 25, groups: 25, text: 1000, formats: 20, format: 100, artists: 50, phrase: 200, tracks: 100, values: 305, reviewValues: REVIEW_LOOKUP_LIMITS.answers, pairs: 100,
    progress: 100 });
const releaseIdPattern = /^(?:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|[1-9]\d{0,11})$/;

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const oneOf = <T>(value: unknown, allowed: readonly T[]): value is T => allowed.includes(value as T);
const list = (value: unknown): unknown[] => Array.isArray(value) ? value : [];
const text = (value: unknown, max: number = LIMITS.text): string | null => typeof value === 'string' && value.length <= max ? value : null;
const count = (value: unknown): number | null => Number.isSafeInteger(value) && (value as number) >= 0 ? value as number : null;
/** Days per month; February gains a day in a Gregorian leap year. */
const monthDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
/** A calendar date at year, month or day precision, as the Web's strict date schema reads it; anything else shows as unknown. */
const date = (value: unknown): ImportDate | null => {
    if (!isRecord(value) || !Number.isSafeInteger(value.year) || (value.year as number) < 1 || (value.year as number) > 9999) return null;
    const year = value.year as number, month = value.month, day = value.day;
    if (month !== null && (!Number.isSafeInteger(month) || (month as number) < 1 || (month as number) > 12)) return null;
    if (day !== null) {
        if (month === null || !Number.isSafeInteger(day) || (day as number) < 1) return null;
        const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
        if ((day as number) > monthDays[(month as number) - 1] + (month === 2 && leap ? 1 : 0)) return null;
    }
    return { year, month: month as number | null, day: day as number | null };
};
const key = (value: unknown): string | null => lookupCandidateSource(value) !== null ? value as string : null;
/** A release ID that agrees with its candidate key (`<source>:<releaseId>`), or null. */
const releaseIdFor = (candidateKey: string | null, value: unknown): string | null =>
    candidateKey !== null && typeof value === 'string' && releaseIdPattern.test(value) && candidateKey === `${lookupCandidateSource(candidateKey)}:${value}` ? value : null;

/** A group's proposal within the view's bounds, or null when any part is out of them. */
function proposalView(raw: unknown): LookupProposal | null {
    if (!isRecord(raw)) return null;
    const albumTitle = text(raw.albumTitle), artists = list(raw.artists), tracks = list(raw.tracks);
    if (albumTitle === null || artists.length > LIMITS.artists || tracks.length > LIMITS.tracks || (raw.label !== null && text(raw.label) === null)) return null;
    // A proposal stored before entries carried MusicBrainz IDs shows none.
    const entries = artists.map(entry => isRecord(entry) && text(entry.name) !== null && oneOf(entry.role, ['primary', 'featured'] as const)
        && (entry.joinPhrase === null || text(entry.joinPhrase, LIMITS.phrase) !== null)
        ? { name: entry.name as string, role: entry.role, joinPhrase: entry.joinPhrase as string | null, musicBrainzId: normalizeMusicBrainzId(entry.musicBrainzId) } : null);
    const numbered = tracks.map(track => isRecord(track) && count(track.discNumber) !== null && count(track.trackNumber) !== null && text(track.title) !== null
        ? { discNumber: track.discNumber as number, trackNumber: track.trackNumber as number, title: track.title as string } : null);
    if (entries.some(entry => entry === null) || numbered.some(track => track === null)) return null;
    return { albumTitle, artists: entries as LookupProposal['artists'], label: raw.label as string | null,
        labelMusicBrainzId: raw.label === null ? null : normalizeMusicBrainzId(raw.labelMusicBrainzId), releaseDate: raw.releaseDate === null ? null : date(raw.releaseDate),
        tracks: numbered as LookupProposal['tracks'] };
}

const position = (value: unknown, max: number): number | null => Number.isSafeInteger(value) && (value as number) >= 1 && (value as number) <= max ? value as number : null;
/**
 * A review candidate's subset comparison within bounds: pairs and unpairable members of this review's slots only (another slot's
 * are dropped), at most 100 pairs with Disc and Track Numbers within the expected tracklist's bounds, and safe non-negative
 * counts; anything else out of bounds shows no subset comparison.
 */
function subsetView(raw: unknown, slots: ReadonlySet<string>): ViewSubsetComparison | null {
    if (!isRecord(raw) || !Array.isArray(raw.pairs) || !Array.isArray(raw.unpairableSlotIds) || raw.pairs.length > LIMITS.pairs || raw.unpairableSlotIds.length > LIMITS.pairs) return null;
    const leftOutTracks = count(raw.leftOutTracks), missingTrackCount = raw.missingTrackCount === null ? null : count(raw.missingTrackCount);
    const pairing = raw.pairing === null ? null : oneOf(raw.pairing, ['unique', 'ambiguous', 'none'] as const) ? raw.pairing : undefined;
    if (leftOutTracks === null || (raw.missingTrackCount !== null && missingTrackCount === null) || pairing === undefined) return null;
    const pairs: ViewSubsetComparison['pairs'] = [];
    for (const pair of raw.pairs) {
        const discNumber = isRecord(pair) ? position(pair.discNumber, LOOKUP_EXPECTED_TRACKLIST_BOUNDS.disc) : null;
        const trackNumber = isRecord(pair) ? position(pair.trackNumber, LOOKUP_EXPECTED_TRACKLIST_BOUNDS.track) : null;
        if (!isRecord(pair) || typeof pair.slotId !== 'string' || discNumber === null || trackNumber === null) return null;
        if (slots.has(pair.slotId)) pairs.push({ slotId: pair.slotId, discNumber, trackNumber });
    }
    if (raw.unpairableSlotIds.some(slot => typeof slot !== 'string')) return null;
    return { leftOutTracks, pairing, pairs, missingTrackCount, unpairableSlotIds: [...new Set((raw.unpairableSlotIds as string[]).filter(slot => slots.has(slot)))] };
}

/** A ranked candidate's counts and differences; the per-file comparison stays internal. A review's also carries its subset comparison. */
function comparisonView(raw: unknown, mode: ViewMode, slots: ReadonlySet<string>): ViewReviewComparison | ViewComparison | null {
    if (!isRecord(raw) || !isRecord(raw.trackCount) || !isRecord(raw.discCount)) return null;
    const local = count(raw.trackCount.local), candidate = count(raw.trackCount.candidate), discs = count(raw.discCount.candidate);
    const unknownLocal = count(raw.unknownLocalDurations), unknownCandidate = count(raw.unknownCandidateDurations);
    if (local === null || candidate === null || discs === null || unknownLocal === null || unknownCandidate === null) return null;
    const known = mode === 'review' ? reviewDifferences : differences;
    const view: ViewComparison = { trackCount: { local, candidate }, discCount: { local: count(raw.discCount.local), candidate: discs },
        // Distinct known differences only, so at most the kinds the Web schema allows (the three of an import's view).
        differences: [...new Set(list(raw.differences).filter((difference): difference is LookupDifference => oneOf(difference, known)))],
        unknownLocalDurations: unknownLocal, unknownCandidateDurations: unknownCandidate };
    return mode === 'review' ? { ...view, subset: subsetView(raw.subset, slots) } : view;
}

/** One candidate's evidence: the fetched release's, else its search summary's, each text bounded (over the bound shows as unknown). */
function candidateView(stored: Record<string, unknown>, ranked: Record<string, unknown> | null, mode: ViewMode, slots: ReadonlySet<string>): ViewCandidate<ViewReviewComparison | ViewComparison> | null {
    const candidateKey = key(stored.key), releaseId = releaseIdFor(candidateKey, stored.releaseId), origin = lookupCandidateSource(candidateKey);
    if (!candidateKey || !releaseId || !origin || (stored.source !== undefined && stored.source !== origin)) return null;
    const itunes = origin === 'itunes', check = itunes && isRecord(stored.itunes) ? stored.itunes.check : null;
    const release = stored.details === 'fetched' && isRecord(stored.release) ? stored.release as Partial<MusicBrainzRelease> : null;
    const summary = !itunes && isRecord(stored.summary) ? stored.summary as Partial<MusicBrainzReleaseSummary> : null;
    const source = release ?? summary;
    const credits = list(source?.artistCredit).filter(isRecord);
    const joined = credits.every(credit => typeof credit.name === 'string' && typeof credit.joinPhrase === 'string')
        ? credits.map(credit => `${credit.name as string}${credit.joinPhrase as string}`).join('') : null;
    const labels = list(source?.labels).filter(isRecord);
    const formats = release ? list(release.media).map(medium => isRecord(medium) ? medium.format : null) : list(summary?.media).map(medium => isRecord(medium) ? medium.format : null);
    return {
        key: candidateKey, releaseId, source: origin, notChecked: itunes && (check === 'unavailable' || check === 'notRun'),
        status: ranked && oneOf(ranked.status, statuses) ? ranked.status : 'incomplete',
        title: text(source?.title), artist: joined ? text(joined) : null,
        // iTunes reports no label, catalogue number, country or medium; its only barcode is one a UPC lookup found.
        label: itunes ? null : text(labels.find(label => typeof label.name === 'string')?.name ?? null),
        catalogNumber: itunes ? null : text(labels.find(label => typeof label.catalogNumber === 'string')?.catalogNumber ?? null),
        barcode: !itunes ? text(source?.barcode ?? null, 14) : typeof source?.barcode === 'string' && /^\d{8,14}$/.test(source.barcode) ? source.barcode : null,
        country: itunes ? null : text(source?.country ?? null, 2), date: date(source?.date ?? null),
        formats: itunes ? [] : formats.filter((format): format is string => typeof format === 'string' && format.length <= LIMITS.format).slice(0, LIMITS.formats),
        trackCount: release ? list(release.media).reduce<number>((sum, medium) => sum + list(isRecord(medium) ? medium.tracks : null).length, 0) : count(summary?.trackCount),
        comparison: ranked ? comparisonView(ranked.comparison, mode, slots) : null,
        groupKey: ranked && typeof ranked.groupKey === 'string' && /^[a-f0-9]{64}$/.test(ranked.groupKey) ? ranked.groupKey : null,
        artistMismatch: ranked && typeof ranked.artistMismatch === 'boolean' ? ranked.artistMismatch : null,
        artwork: release?.frontArtwork === true,
        // Only `true` is ever sent, so a Web tab opened before Track-title searches still parses every other review candidate.
        ...(mode === 'review' && stored.basis === 'trackTitle' ? { byTrackTitle: true } : {})
    };
}

/**
 * A review's applied pairing within bounds: null, or at most 100 pairs of this review's slots, each once, with Disc and Track
 * Numbers within the expected tracklist's bounds; any other value reads as null.
 */
function appliedPairsView(raw: unknown, slots: ReadonlySet<string>): NonNullable<ImportLookupView['applied']>['pairs'] {
    if (!Array.isArray(raw) || raw.length > LIMITS.pairs) return null;
    const pairs: { slotId: string; discNumber: number; trackNumber: number }[] = [], seen = new Set<string>();
    for (const pair of raw) {
        const discNumber = isRecord(pair) ? position(pair.discNumber, LOOKUP_EXPECTED_TRACKLIST_BOUNDS.disc) : null;
        const trackNumber = isRecord(pair) ? position(pair.trackNumber, LOOKUP_EXPECTED_TRACKLIST_BOUNDS.track) : null;
        if (!isRecord(pair) || typeof pair.slotId !== 'string' || !slots.has(pair.slotId) || seen.has(pair.slotId) || discNumber === null || trackNumber === null) return null;
        seen.add(pair.slotId); pairs.push({ slotId: pair.slotId, discNumber, trackNumber });
    }
    return pairs;
}

/**
 * Applied values, conflicts and flags of the shown project; a conflict's lookup value is re-read through the draft rules or dropped.
 * A review's also admits its review-only paths and flag reasons, marks each conflict's `precision` and carries its `pairs`.
 */
function appliedView(raw: unknown, doc: AdminImportDocument, slots: ReadonlySet<string>, mode: ViewMode): ImportLookupView['applied'] {
    if (!isRecord(raw) || !Number.isSafeInteger(raw.run) || (raw.run as number) < 1 || !oneOf(raw.choice, ['preselected', 'chosen', 'none'] as const)) return null;
    const review = mode === 'review', bound = review ? LIMITS.reviewValues : LIMITS.values, reasons = review ? reviewFlagReasons : flagReasons;
    const draft = importDraftV2View(doc.draft, doc.manifest, doc._id.toHexString());
    const path = (value: unknown): value is ImportDraftPath => isLookupValuePath(value, { review }) && (!value.startsWith('tracks.') || slots.has(value.split('.')[1]));
    const slot = (value: string) => value.startsWith('tracks.') ? value.split('.')[1] : null;
    const conflicts: NonNullable<ImportLookupView['applied']>['conflicts'] = [];
    for (const item of list(raw.conflicts).slice(0, bound)) {
        if (!isRecord(item) || !path(item.path) || !(item.answer === null || item.answer === 'mine' || item.answer === 'lookup')) continue;
        // A lookup value is never empty, so an empty stored one is as unreadable as an invalid one. Its MusicBrainz IDs came from the
        // release, so they are read as introduced.
        let lookup: unknown; try { lookup = parseDraftValue(item.path, item.lookup, draft, { introduce: lookupValueIds(item.lookup) }); } catch { continue; }
        if (lookup !== null && lookup !== '') conflicts.push({ path: item.path, slotId: slot(item.path), lookup, answer: item.answer, musicBrainzId: item.musicBrainzId === true,
            ...(review ? { precision: item.precision === true } : {}) });
    }
    const candidateKey = key(raw.candidateKey), itunes = lookupCandidateSource(candidateKey) === 'itunes' && raw.source === 'itunes';
    return {
        run: raw.run as number, candidateKey, releaseId: releaseIdFor(candidateKey, raw.releaseId),
        choice: raw.choice, basis: oneOf(raw.basis, [...(review ? reviewBases : bases), 'chosen']) ? raw.basis as LookupApplication['basis'] : null,
        source: itunes ? 'itunes' : 'musicbrainz', notChecked: itunes && raw.notChecked === true,
        values: list(raw.values).slice(0, bound).filter((item): item is Record<string, unknown> & { path: string } => isRecord(item) && path(item.path)).map(item => ({ path: item.path, slotId: slot(item.path) })),
        conflicts,
        flagged: list(raw.flagged).slice(0, bound).filter((item): item is Record<string, unknown> & { path: string } => isRecord(item) && path(item.path) && oneOf(item.reason, reasons))
            .map(item => ({ path: item.path, reason: item.reason as LookupApplication['flagged'][number]['reason'] })),
        ...(review ? { pairs: appliedPairsView(raw.pairs, slots) } : {})
    };
}

/**
 * A stored time as an ISO string, or null when it is not a valid Date or falls outside the years 0000-9999, whose extended form
 * ("+010000-…") the Web's strict date-time schema refuses.
 */
const instant = (value: unknown): string | null => {
    if (!(value instanceof Date) || !Number.isFinite(value.getTime())) return null;
    const iso = value.toISOString();
    return /^\d{4}-/.test(iso) ? iso : null;
};
/**
 * A review's active run's progress from stored counters and times only, never a query: in `search` the planned searches sent
 * (`queryIndex` of `queries`, also while queued; the trailing Track-title searches count only once they are being sent, as the run
 * often skips them), in `details` the candidates whose details are no longer pending, in `itunes` the
 * iTunes requests sent or, once they all were, the collection lookups settled, in `bridge` the bridge searches sent and in `aliases`
 * the alias lookups no longer pending; `done` never exceeds `total`, which stays within 100. Null for a run that is not queued,
 * running or retrying, an unknown phase or an unreadable start or last-step time.
 */
function progressView(raw: Record<string, unknown>): ViewLookupProgress | null {
    const startedAt = instant(raw.createdAt), updatedAt = instant(raw.updatedAt), phase = raw.phase;
    if (!isBlockingLookupState(raw.state) || !oneOf(phase, progressPhases) || !startedAt || !updatedAt) return null;
    const settled = (entries: unknown[], field: string) => entries.filter(entry => isRecord(entry) && entry[field] !== 'pending').length;
    const candidates = list(raw.candidates), aliases = list(raw.aliases), stage = storedItunesStage(raw.itunesStage);
    const collections = stage?.items.filter(item => item.collection !== 'notNeeded') ?? [];
    const queries = list(raw.queries), titled = queries.findIndex(isTrackTitleLookupQuery);
    const planned = titled >= 0 && raw.trackTitleSearch !== 'sent' ? titled : queries.length;
    const [done, total] = phase === 'search' ? [count(raw.queryIndex) ?? 0, planned]
        : phase === 'details' ? [settled(candidates, 'details'), candidates.length]
        : phase === 'aliases' ? [settled(aliases, 'state'), aliases.length]
        : !stage ? [0, 0]
        : phase === 'bridge' ? [stage.bridgeIndex, stage.bridge?.length ?? 0]
        : stage.requestIndex < stage.requests.length ? [stage.requestIndex, stage.requests.length]
        : [settled(collections, 'collection'), collections.length];
    const bound = Math.min(total, LIMITS.progress);
    return { phase, done: Math.min(done, bound), total: bound, startedAt, updatedAt };
}

/**
 * The view of a record, or null for a record this release cannot read (an unknown state, run or input). Candidates follow the
 * ranking's order when the run was ranked, else the stored order as incomplete. `needsAnswer` and `blocking` are what Publish (or
 * applying a review) waits for; for an import an explicit Album reuse decision counts as an append, and a review never appends.
 */
function lookupRecordView(record: MetadataLookupRecord, doc: AdminImportDocument, mode: ViewMode): CatalogReviewLookupView | null {
    const raw = record as unknown as Record<string, unknown>;
    if (!isRecord(raw) || !oneOf(raw.state, states) || !Number.isSafeInteger(raw.run) || (raw.run as number) < 1) return null;
    const input = isRecord(raw.input) ? raw.input : null;
    if (!input || !oneOf(input.trigger, mode === 'review' ? reviewTriggers : triggers)) return null;
    // A submitted Artist name is projected only when it is a bounded string, so a run without one gives the same view as before.
    const submitted = isRecord(input.submitted) && oneOf(input.submitted.kind, ['album', 'song'] as const) && text(input.submitted.text) !== null
        ? { kind: input.submitted.kind, text: input.submitted.text as string,
            ...(text(input.submitted.artist) !== null ? { artist: input.submitted.artist as string } : {}) } : null;
    const stored = list(raw.candidates).filter(isRecord), ranking = isRecord(raw.ranking) ? raw.ranking : null;
    const ranked = ranking ? list(ranking.candidates).filter(isRecord) : [];
    const ordered: [Record<string, unknown>, Record<string, unknown> | null][] = ranking
        ? ranked.map(entry => [stored.find(candidate => candidate.key === entry.key), entry] as const).filter((pair): pair is [Record<string, unknown>, Record<string, unknown>] => Boolean(pair[0]))
        : stored.map(candidate => [candidate, null]);
    const slots = new Set((Array.isArray(doc.manifest?.files) ? doc.manifest.files : []).map(file => file.slotId));
    const candidates = ordered.map(([candidate, entry]) => candidateView(candidate, entry, mode, slots))
        .filter((candidate): candidate is ViewCandidate<ViewReviewComparison> => candidate !== null).slice(0, LIMITS.candidates);
    const groups = (ranking ? list(ranking.groups) : []).filter(isRecord).map(group => {
        const proposal = proposalView(group.proposal), memberKeys = list(group.memberKeys).map(key);
        return typeof group.groupKey === 'string' && /^[a-f0-9]{64}$/.test(group.groupKey) && key(group.representativeKey) && proposal && memberKeys.length <= LIMITS.candidates && memberKeys.every(Boolean)
            ? { groupKey: group.groupKey, representativeKey: key(group.representativeKey)!, memberKeys: memberKeys as string[], proposal } : null;
    }).filter((group): group is ImportLookupView['groups'][number] => group !== null).slice(0, LIMITS.groups);
    const preselection = ranking && isRecord(ranking.preselection) && key(ranking.preselection.candidateKey) && oneOf(ranking.preselection.basis, mode === 'review' ? reviewBases : bases)
        ? { candidateKey: ranking.preselection.candidateKey as string, basis: ranking.preselection.basis as LookupPreselection['basis'], artistMismatch: ranking.preselection.artistMismatch === true,
            notChecked: lookupCandidateSource(ranking.preselection.candidateKey) === 'itunes' && ranking.preselection.notChecked === true } : null;
    const disclosure = ranking && isRecord(ranking.disclosure) && count(ranking.disclosure.unknownLocalDurations) !== null && count(ranking.disclosure.unknownLocalDiscNumbers) !== null
        ? { unknownLocalDurations: ranking.disclosure.unknownLocalDurations as number, unknownLocalDiscNumbers: ranking.disclosure.unknownLocalDiscNumbers as number,
            partialComparison: ranking.disclosure.partialComparison === true } : null;
    const append = mode === 'import' && list(doc.decisions).some(decision => isRecord(decision) && decision.scope === 'album' && decision.action === 'reuse');
    const needed = lookupAnswersNeeded(record, doc, { append });
    // An active run's iTunes request (a search, UPC or collection lookup) is running, or retrying while it waits for its automatic
    // retry; a stage still running while the run is no longer blocking ended with it (stopped, superseded or unavailable) unanswered.
    const stage = storedItunesStage(raw.itunesStage), blocking = isBlockingLookupState(raw.state), progress = mode === 'review' ? progressView(raw) : null;
    const itunes: ImportLookupItunesStatus = !stage ? 'notQueried' : stage.state !== 'unavailable' && blocking && raw.phase === 'itunes' ? raw.state === 'retrying' ? 'retrying' : 'running'
        : stage.state !== 'running' ? stage.state : blocking ? 'running' : 'notQueried';
    return {
        run: raw.run as number, state: raw.state, issue: oneOf(raw.issue, issues) ? raw.issue : null,
        outcome: oneOf(raw.outcome, ['candidates', 'noRelease', 'noQuery'] as const) ? raw.outcome : null,
        input: { trigger: input.trigger, submitted }, candidates, groups, preselection, disclosure,
        applied: appliedView(raw.applied, doc, slots, mode),
        staleFiles: [...new Set(list(raw.staleSlotIds).filter((slot): slot is string => typeof slot === 'string' && slots.has(slot)))],
        needsAnswer: { tie: needed.tie, conflicts: needed.conflicts.filter(path => !path.startsWith('tracks.') || slots.has(path.split('.')[1])) },
        blocking: blocking || needed.tie || needed.conflicts.length > 0, itunes, ...(progress ? { progress } : {})
    };
}

/** An import's view (GET /imports/:id/lookup); null for a record this release cannot read, a review's `catalog` run included. */
export const importLookupView = (record: MetadataLookupRecord, doc: AdminImportDocument): ImportLookupView | null =>
    lookupRecordView(record, doc, 'import') as ImportLookupView | null;
/** An existing-Album review's view (GET /catalog-reviews/:id/lookup); null for a record this release cannot read. */
export const catalogReviewLookupView = (record: MetadataLookupRecord, doc: AdminImportDocument): CatalogReviewLookupView | null => lookupRecordView(record, doc, 'review');
